</dependency>
<dependency>
    <groupId>io.github.resilience4j</groupId>
    <artifactId>resilience4j-reactor</artifactId>
    <version>1.7.0</version>
</dependency>
```

2. Configure the rate limiter:

In your `application.yml` file, add the following configuration:
```yaml
resilience4j.ratelimiter:
  configs:
    default: # Default rate limiter configuration
      limitForPeriod: 10 # Number of requests allowed per period
      limitRefreshPeriod: 1000ms # Time period to refresh the limit
      timeoutDuration: 0 # Timeout duration for requests (set to 0 to disable timeout)
  instances:
    yourRateLimiter: # Custom rate limiter instance
      baseConfig: default # Reference to the default config
```

3. Implement rate limiter in your service class:

Create a service class that will act as a client to access your API:
```java
import io.github.resilience4j.ratelimiter.annotation.RateLimiter;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;

@Service
public class ApiService {
    private final RestTemplate restTemplate;

    public ApiService(RestTemplate restTemplate) {
        this.restTemplate = restTemplate;
    }

    @RateLimiter(name = "yourRateLimiter")
    public String getApiResponse() {
        // Replace this with the actual API call you want to rate limit
        return restTemplate.getForObject("https://your-api-endpoint.com/", String.class);
    }
}
```

Now, the `getApiResponse` method is rate-limited according to the configuration you specified in the `application.yml` file.

4. Autowire the ApiService:

In your controller class, autowire the new ApiService class and use it:
```java
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class ApiController {
    private final ApiService apiService;

    public ApiController(ApiService apiService) {
        this.apiService = apiService;
    }

    @GetMapping("/limited")
    public String rateLimitedEndpoint() {
        return apiService.getApiResponse();
    }
}
```

Now, when you call the `/limited` endpoint, it will enforce the rate limiting as configured.

