Once installed, the following is the code for your `redis.js` file in the `utils` folder.

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = redis.createClient();
    this.client.on('error', (error) => {
      console.error(`Redis client not connected: ${error.message}`);
    });
  }

  isAlive() {
    return this.client.connected;
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (error, response) => {
        if (error) reject(error);
        resolve(response);
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.setex(key, duration, value, (error, response) => {
        if (error) reject(error);
        resolve(response);
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (error, response) => {
        if (error) reject(error);
        resolve(response);
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = { redisClient };
```

This code snippet creates a `RedisClient` class as you described, handling connection, getting, setting, and deleting key-value pairs with Redis. Furthermore, it exports a pre-initialized instance named "redisClient" that you can import and use throughout your project. Enjoy rediscovering the magic of Redis in your application!

