```csharp
public class StudentController : Controller
{
    private readonly StudentDbContext _context;
    private readonly IStudentRepository _studentRepository;

    public StudentController(StudentDbContext context, IStudentRepository studentRepository)
    {
        _context = context;
        _studentRepository = studentRepository;
    }

    [HttpGet]
    public IActionResult Create()
    {
        return View();
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public IActionResult Create([Bind("Name,Age")] Student student)
    {
        if (ModelState.IsValid)
        {
            try
            {
                _studentRepository.AddStudent(student);
                _context.SaveChanges();
                return RedirectToAction(nameof(Index));
            }
            catch (DbUpdateException ex)
            {
                for (int i = 0; i < ex.EntityEntry.Properties.Count; i++)
                {
                    if (ex.EntityEntry.Properties[i].IsModified)
                    {
                        ModelState.AddModelError(ex.EntityEntry.Properties[i].Name, ex.EntityEntry.Properties[i].ErrorMessage);
                    }
                }
            }
            catch (Exception ex)
            {
                ModelState.AddModelError(string.Empty, ex.Message);
            }
        }

        return View(student);
    }

    public IActionResult Index()
    {
        var students = _studentRepository.GetAllStudents();
        return View(students);
    }
}
```
