import CryptoSwift

func encrypt(data: Data, key: String, iv: String) -> Data? {
    do {
        let aes = try AES(key: key, iv: iv)
        let encryptedData = try aes.encrypt(data.bytes)
        return Data(encryptedData)
    } catch {
        // Handle encryption error
        return nil
    }
}

func decrypt(data: Data, key: String, iv: String) -> Data? {
    do {
        let aes = try AES(key: key, iv: iv)
