```swift
import PDFKit

func passwordProtectPDF(inputURL: URL, outputURL: URL, password: String) {
    guard let document = PDFDocument(url: inputURL) else { return }
    let newDocument = PDFDocument()

    for index in 0..<document.pageCount {
        if let page = document.page(at: index) {
            // Add pages from the original document to the new document
            newDocument.insert(page, at: index)
        }
