    <div class="container">
        <h1 class="animate">Animate this heading when it's in the viewport</h1>
        <p>Lorem ipsum dolor sit amet...</p>
    </div>

    <script src="script.js"></script>
</body>
</html>
```

2. Add CSS
Create an `styles.css` file, and define your animation and a class that will trigger the animation when added through JavaScript:

```css
/* Adding some basic styles */
.container {
  max-width: 800px;
  margin: auto;
}

/* Animation properties */
.animate {
  opacity: 0;
  transform: translateY(50px);
  transition: all 0.5s ease-out; /* You can customize the duration and easing function here */
}

.animate.visible {
  opacity: 1;
  transform: translateY(0);
}
```

3. Create JavaScript code
In your `script.js` file, use JavaScript (or jQuery) to detect the scrolling and calculate if the element is visible in the viewport, and toggle the `.visible` class accordingly:

```javascript
document.addEventListener('DOMContentLoaded', function () {
  const animateElements = document.querySelectorAll('.animate');

  // Function to check if element is in the viewport
  const isInViewport = (element) => {
    const rect = element.getBoundingClientRect();
    return (
      rect.top >= 0 &&
      rect.left >= 0 &&
      rect.bottom <= (window.innerHeight || document.documentElement.clientHeight) &&
      rect.right <= (window.innerWidth || document.documentElement.clientWidth)
    );
  };

  // Function to add visible class to elements in the viewport
  const checkVisibility = () => {
    animateElements.forEach((element) => {
      if (isInViewport(element)) {
        element.classList.add('visible');
      }
    });
  };

  // Check visibility on load and scroll
  checkVisibility(); // Check on load
  window.addEventListener('scroll', checkVisibility); // Check on scroll
});
```

Now, with this setup, elements with the `.animate` class will be animated using CSS whenever they enter the viewport during scrolling. You can customize the CSS animation as per your desired style and timing.

